      SUBROUTINE SEEDIT      INCLUDE 'ISEEDX.CIN'      INCLUDE 'NUMREP.CIN'C      CHARACTER*1     BLANK      DATA BLANK /' '/C      JS = 81      DO 10 J = 1, 80      JS = 81 - J      IF (NUMREP(JS:JS) .EQ. BLANK) GO TO 20   10 CONTINUE   20 IF (JS .GE. 65) THEN        DO 30 J = 65, JS        NUMREP(J:J) = '0'   30   CONTINUE      ENDIF      READ (NUMREP(65:80),9002) ISEEDX 9002 FORMAT (4I4)      ISEEDX(4) = 2*(ISEEDX(4)/2) + 1      RETURN      END